function db():PDO{$p=parse_url(getenv('DATABASE_URL')?:'');if(!$p||empty($p['host'])||empty($p['user'])||empty($p['path']))throw new RuntimeException('Database is not configured');return new PDO('pgsql:host='.$p['host'].';port='.($p['port']??5432).';dbname='.ltrim($p['path'],'/'),urldecode($p['user']),urldecode($p['pass']??''),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}
function setup(PDO $d):void{$d->exec("CREATE TABLE IF NOT EXISTS app_chat_users (id BIGSERIAL PRIMARY KEY, identity_key VARCHAR(255) UNIQUE NOT NULL, display_name VARCHAR(150) NOT NULL, last_seen TIMESTAMPTZ DEFAULT now()); CREATE TABLE IF NOT EXISTS app_chat_messages(id BIGSERIAL PRIMARY KEY,sender_id BIGINT NOT NULL REFERENCES app_chat_users(id),recipient_id BIGINT NOT NULL REFERENCES app_chat_users(id),body TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now(),read_at TIMESTAMPTZ); CREATE INDEX IF NOT EXISTS chat_msg_pair ON app_chat_messages(sender_id,recipient_id,id); CREATE TABLE IF NOT EXISTS app_chat_calls(id BIGSERIAL PRIMARY KEY,caller_id BIGINT NOT NULL REFERENCES app_chat_users(id),callee_id BIGINT NOT NULL REFERENCES app_chat_users(id),kind VARCHAR(10) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'ringing',created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now()); CREATE TABLE IF NOT EXISTS app_chat_signals(id BIGSERIAL PRIMARY KEY,call_id BIGINT NOT NULL REFERENCES app_chat_calls(id) ON DELETE CASCADE,sender_id BIGINT NOT NULL REFERENCES app_chat_users(id),payload JSONB NOT NULL,created_at TIMESTAMPTZ DEFAULT now());");}
function ensureDelivery(PDO $d):void{$d->exec("ALTER TABLE app_chat_messages ADD COLUMN IF NOT EXISTS delivered_at TIMESTAMPTZ");}
function setupAttachments(PDO $d):void{$d->exec("CREATE TABLE IF NOT EXISTS app_chat_attachments (message_id BIGINT PRIMARY KEY REFERENCES app_chat_messages(id) ON DELETE CASCADE, filename VARCHAR(255) NOT NULL, mime VARCHAR(120) NOT NULL, bytes BYTEA NOT NULL)");}
function setupAdvanced(PDO $d):void{$d->exec("CREATE TABLE IF NOT EXISTS app_chat_uploads (token VARCHAR(64) PRIMARY KEY, sender_id BIGINT NOT NULL, recipient_id BIGINT NOT NULL, filename VARCHAR(255) NOT NULL, caption TEXT NOT NULL DEFAULT '', total_size BIGINT NOT NULL, mime VARCHAR(120) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE TABLE IF NOT EXISTS app_chat_upload_chunks (token VARCHAR(64) NOT NULL REFERENCES app_chat_uploads(token) ON DELETE CASCADE, part INT NOT NULL, bytes BYTEA NOT NULL, PRIMARY KEY(token,part)); CREATE INDEX IF NOT EXISTS chat_uploads_owner ON app_chat_uploads(sender_id,created_at);");}
function setupMessageControls(PDO $d):void{$d->exec("CREATE TABLE IF NOT EXISTS app_chat_message_hidden (message_id BIGINT NOT NULL REFERENCES app_chat_messages(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES app_chat_users(id) ON DELETE CASCADE,PRIMARY KEY(message_id,user_id)); ALTER TABLE app_chat_messages ADD COLUMN IF NOT EXISTS reply_to BIGINT NULL REFERENCES app_chat_messages(id) ON DELETE SET NULL; CREATE INDEX IF NOT EXISTS chat_hidden_user ON app_chat_message_hidden(user_id,message_id); ALTER TABLE app_chat_messages ADD COLUMN IF NOT EXISTS deleted_for_everyone_at TIMESTAMPTZ;");}
function setupEdits(PDO $d):void{$d->exec("ALTER TABLE app_chat_messages ADD COLUMN IF NOT EXISTS edited_at TIMESTAMPTZ; CREATE TABLE IF NOT EXISTS app_chat_message_edits (id BIGSERIAL PRIMARY KEY,message_id BIGINT NOT NULL REFERENCES app_chat_messages(id) ON DELETE CASCADE,edited_at TIMESTAMPTZ NOT NULL DEFAULT now())");}
function chatAllowedMime(string $mime):bool{return in_array($mime,['image/jpeg','image/png','image/gif','image/webp','video/mp4','video/webm','audio/mpeg','audio/mp4','audio/ogg','audio/wav','audio/webm','video/webm','application/pdf','text/plain','text/csv','application/zip','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.openxmlformats-officedocument.presentationml.presentation'],true);}
function chatStoreAttachment(PDO $d,int $me,int $other,string $caption,string $filename,string $mime,string $data):int{
 if(strlen($data)<1||strlen($data)>15*1048576||!chatAllowedMime($mime))reply(['error'=>'Unsupported or oversized attachment'],422);
 $tmp=fopen('php://temp','w+');fwrite($tmp,$data);rewind($tmp);$real=(new finfo(FILEINFO_MIME_TYPE))->buffer($data);fclose($tmp);
 if(!chatAllowedMime($real))reply(['error'=>'Unsupported file contents'],422);
 $d->beginTransaction();try{$q=$d->prepare('INSERT INTO app_chat_messages(sender_id,recipient_id,body) VALUES (?,?,?) RETURNING id');$q->execute([$me,$other,$caption]);$mid=(int)$q->fetchColumn();$q=$d->prepare('INSERT INTO app_chat_attachments(message_id,filename,mime,bytes) VALUES (?,?,?,?)');$q->bindValue(1,$mid);$q->bindValue(2,$filename);$q->bindValue(3,$real);$q->bindValue(4,$data,PDO::PARAM_LOB);$q->execute();$d->commit();return $mid;}catch(Throwable $e){$d->rollBack();throw $e;}
}
