</style></head><body><div class="app" id="app"><aside class="side"><div class="side-top"><div class="brand-row"><div class="brand">💬 Messages</div><button type="button" class="search-toggle" id="searchToggle" aria-label="Search colleagues" aria-expanded="false" title="Search colleagues"><svg viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg></button></div><input class="search" id="search" placeholder="Search colleagues…" aria-label="Search colleagues" hidden></div><div class="users" id="users"></div></aside><main class="main"><header class="head"><button class="back" id="back" aria-label="Back to contacts">‹</button><span class="avatar" id="headAvatar">✦</span><div style="min-width:0"><strong id="headName">Team conversations</strong><div class="hint" id="headStatus">Select a contact to chat</div></div><div class="actions"><button class="action" id="audio" title="Audio call" disabled>☎ Audio</button><button class="action" id="video" title="Video call" disabled>▣ Video</button></div></header><div class="notice" id="notice"<?=isset($startupError)?' style="display:block"':''?>><?=isset($startupError)?htmlspecialchars($startupError,ENT_QUOTES,'UTF-8'):''?></div><div class="messages" id="messages"><div class="empty"><b>Start a conversation</b><div>Select a colleague from the contact list to view messages.</div></div></div><div id="replyBar" hidden class="reply-bar"><span id="replyText"></span><button type="button" id="replyCancel" aria-label="Cancel reply">✕</button></div><form class="compose" id="compose"><label class="attach-button" for="attachment" title="Attach photo, video or file" aria-label="Attach file">＋</label><input type="file" id="attachment" multiple accept="image/*,video/mp4,video/webm,audio/*,.pdf,.txt,.csv,.zip,.docx,.xlsx,.pptx" hidden><button type="button" id="recordVoice" class="attach-button" title="Record a voice note" aria-label="Record voice note" style="font-size:20px">🎙</button><textarea id="body" placeholder="Write a message…" aria-label="Message" disabled></textarea><button class="send" id="send" disabled>Send ➤</button></form></main></div><div class="attach-modal" id="attachModal" role="dialog" aria-modal="true" aria-label="Review attachments" hidden><div class="attach-dialog"><div class="attach-top"><strong>Send attachments</strong><button type="button" id="attachClose" aria-label="Close">✕</button></div><div class="attach-list" id="attachList"></div><div id="uploadProgress" role="status" aria-live="polite" style="padding:0 18px;font-size:12px;color:#69534a"></div><div class="attach-bottom"><label class="attach-add" for="attachment">＋ Add more</label><span id="attachCount"></span><button type="button" id="attachSend">Send ➤</button></div></div></div><div class="viewer" id="viewer" role="dialog" aria-modal="true" aria-label="Attachment preview" hidden><div class="viewer-head"><span id="viewerName"></span><button type="button" id="viewerClose">✕</button></div><div class="viewer-content" id="viewerContent"></div><a id="viewerDownload" download>Download file</a></div><div class="callbox" id="callbox"><h2 id="calltitle">Calling…</h2><div id="callStatus" role="status" aria-live="polite">Secure WebRTC media transport</div><div id="callTimer" aria-label="Call duration">00:00</div><div class="videos"><video id="remote" autoplay playsinline></video><video id="local" autoplay muted playsinline></video></div><div class="callcontrols"><button class="accept" id="accept" style="display:none">Answer</button><button id="mute">Mute</button><button id="camera">Camera off</button><button id="flipCamera" title="Switch front/rear camera">Flip camera</button><button id="shareScreen" title="Share screen where supported">Share screen</button><button class="hang" id="hang">End call</button></div></div><script>
const csrf=<?=json_encode($chatCsrf??'')?>;let me=<?=json_encode($me??null)?>,selected=null,users=[],lastMessages='',currentCall=null,pc=null,stream=null,lastSignal=0,pendingCandidates=[],answering=false,renderedContacts='',messageBusy=false;
const $=id=>document.getElementById(id);const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(action,data=null,params=''){const r=await fetch('messages.php?action='+action+params,{method:data?'POST':'GET',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:data?JSON.stringify(data):undefined,cache:'no-store'});const j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');return j}
function notify(s){$('notice').textContent=s;$('notice').style.display='block';setTimeout(()=>$('notice').style.display='none',5500)}
function clock(s){if(!s)return '';const d=new Date(s);return isNaN(d)?'':d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}
function renderUsers(){const term=$('search').value.toLowerCase();const html=users.filter(u=>u.display_name.toLowerCase().includes(term)).map(u=>`<button class="user ${selected===+u.id?'selected':''}" data-id="${u.id}"><span class="avatar">${escapeHTML(u.display_name[0]?.toUpperCase()||'?')}</span><span class="user-info"><span class="user-line"><span class="uname">${escapeHTML(u.display_name)}</span><span class="stamp">${clock(u.last_message_at)}</span></span><div class="preview">${escapeHTML(u.last_body||'Start a conversation')}</div></span>${+u.unread?`<span class="count">${u.unread}</span>`:''}</button>`).join('')||'<div class="hint" style="padding:20px">No matching contacts</div>';if(html!==renderedContacts){const scroll=$('users').scrollTop;$('users').innerHTML=html;$('users').scrollTop=scroll;renderedContacts=html;}}
async function refreshUsers(){try{const d=await api('users');if(!Array.isArray(d.users))throw Error('Invalid contact directory response');users=d.users;renderUsers()}catch(e){$('users').innerHTML='<div class="hint" style="padding:20px;line-height:1.6">Unable to load contacts. '+escapeHTML(e.message)+'<br><button type="button" id="retryContacts">Retry</button></div>';$('retryContacts').onclick=refreshUsers;renderedContacts='';notify(e.message)}}
function selectUser(id){replyTarget=null;$('replyBar').hidden=true;selected=id;const u=users.find(x=>+x.id===id);$('headName').textContent=u?.display_name||'Colleague';$('headAvatar').textContent=(u?.display_name||'?')[0].toUpperCase();$('headStatus').textContent='Private conversation';['audio','video','body','send'].forEach(k=>$(k).disabled=false);lastMessages='';$('messages').innerHTML='<div class="empty">Loading conversation…</div>';$('app').classList.add('chat-open');renderUsers();refreshMessages()}
function dayLabel(date){const d=new Date(date),now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate()),yesterday=new Date(today);yesterday.setDate(today.getDate()-1);const day=new Date(d.getFullYear(),d.getMonth(),d.getDate());if(+day===+today)return 'Today';if(+day===+yesterday)return 'Yesterday';return d.toLocaleDateString([],{weekday:'long',day:'numeric',month:'long',year:d.getFullYear()!==now.getFullYear()?'numeric':undefined})}
function attachmentHTML(m){if(!m.filename)return '';const name=escapeHTML(m.filename),mime=m.mime||'';const icon=mime.startsWith('image/')?'🖼️':mime.startsWith('video/')?'🎬':mime.startsWith('audio/')?'🎵':'📄';return `<button type="button" class="file-tile" data-file-id="${Number(m.id)}" data-file-mime="${escapeHTML(mime)}" data-file-name="${name}" title="Tap to preview or download"><span style="font-size:25px">${icon}</span><span>${name}<small style="display:block;opacity:.7">Tap to view file options</small></span></button>`}

async function refreshMessages(){if(!selected||messageBusy)return;const recipient=selected;messageBusy=true;try{const d=await api('messages',null,'&user='+recipient);if(selected!==recipient)return;const key=JSON.stringify(d.messages);if(key===lastMessages)return;lastMessages=key;const el=$('messages'),atBottom=el.scrollHeight-el.scrollTop-el.clientHeight<110;let prevDay='';el.innerHTML=d.messages.length?d.messages.map(m=>{const day=dayLabel(m.created_at),separator=day!==prevDay?`<div class="day-divider">${escapeHTML(day)}</div>`:'';prevDay=day;const mine=+m.sender_id===+me;const status=mine?(m.read_at?'<span class="ticks read" title="Read">✓✓</span>':m.delivered_at?'<span class="ticks" title="Delivered">✓✓</span>':'<span class="ticks" title="Sent">✓</span>'):'';return separator+`<div class="bubble ${mine?'mine':''} ${m.deleted_for_everyone_at?'message-deleted':''}" data-message-id="${Number(m.id)}">${m.deleted_for_everyone_at?'<span class="deleted-note">🚫 This message was deleted</span>':`${m.reply_to?`<button type="button" class="quoted quoted-jump" data-jump-id="${Number(m.reply_to)}">↩ ${escapeHTML(m.reply_deleted?'This message was deleted':m.reply_body||'Original message unavailable')}</button>`:''}${attachmentHTML(m)}${m.body?escapeHTML(m.body):''}`}<div class="meta"><span>${m.edited_at?'<span title="Edited message">Edited · </span>':''}${clock(m.created_at)}</span>${m.deleted_for_everyone_at?'':status}</div><div class="message-tools">${m.deleted_for_everyone_at?'':`<button type="button" data-reply-id="${Number(m.id)}" title="Reply">↩ Reply</button>${mine&&!m.filename&&(Date.now()-new Date(m.created_at).getTime())<900000?`<button type="button" data-edit-id="${Number(m.id)}" title="Edit message">✎ Edit</button>`:''}`}<button type="button" data-delete-id="${Number(m.id)}" data-mine="${mine?'1':'0'}" title="Delete message">⋯</button></div></div>`}).join(''):'<div class="empty">No messages yet. Say hello 👋</div>';if(atBottom||d.messages.length<4)el.scrollTop=el.scrollHeight;}catch(e){notify(e.message)}finally{messageBusy=false}}
$('searchToggle').onclick=()=>{const field=$('search');const open=field.hidden;field.hidden=!open;$('searchToggle').setAttribute('aria-expanded',String(open));if(open)field.focus();else{field.value='';renderUsers()}};
$('users').onclick=e=>{const b=e.target.closest('button[data-id]');if(b)selectUser(+b.dataset.id)};$('search').oninput=renderUsers;$('back').onclick=()=>{$('app').classList.remove('chat-open')};
let staged=[],uploading=false,replyTarget=null,voiceRecorder=null,voiceStream=null,voiceChunks=[],voiceStarted=0;
const maxFile=15*1024*1024;
function sizeLabel(n){return n>=1048576?(n/1048576).toFixed(1)+' MB':Math.ceil(n/1024)+' KB'}
function clearStaged(){staged.forEach(x=>{if(x.url)URL.revokeObjectURL(x.url)});staged=[];$('attachment').value=''}
function closeStage(){if(uploading)return;$('attachModal').hidden=true;clearStaged()}
function renderStage(){const list=$('attachList');list.replaceChildren();staged.forEach((item,i)=>{const row=document.createElement('div');row.className='attach-item';const thumb=document.createElement('div');thumb.className='attach-thumb';if(item.file.type.startsWith('image/')){const img=document.createElement('img');img.src=item.url;img.alt='Selected photo';thumb.append(img)}else if(item.file.type.startsWith('video/')){const v=document.createElement('video');v.src=item.url;v.muted=true;v.playsInline=true;v.preload='none';v.controls=true;thumb.append(v)}else if(item.file.type.startsWith('audio/')){const audio=document.createElement('audio');audio.src=item.url;audio.controls=true;audio.preload='none';audio.style.width='100%';thumb.style.width='100%';thumb.append(audio)}else{thumb.textContent='📄';thumb.style.fontSize='35px'}const detail=document.createElement('div');detail.className='attach-detail';const name=document.createElement('div');name.className='attach-name';name.textContent=item.file.name;const meta=document.createElement('div');meta.className='attach-meta';meta.textContent=sizeLabel(item.file.size);const cap=document.createElement('textarea');cap.className='attach-caption';cap.placeholder='Add a caption (optional)…';cap.maxLength=4000;cap.value=item.caption;cap.disabled=uploading;cap.oninput=()=>item.caption=cap.value;const remove=document.createElement('button');remove.type='button';remove.className='attach-remove';remove.textContent='Remove';remove.disabled=uploading;remove.onclick=()=>{URL.revokeObjectURL(item.url);staged.splice(i,1);if(!staged.length)closeStage();else renderStage()};if(item.file.type.startsWith('video/')&&!uploading){const trim=document.createElement('button');trim.type='button';trim.className='attach-remove';trim.textContent='✂ Trim video';trim.onclick=()=>trimVideo(i);detail.append(trim)}if(item.file.type.startsWith('image/')&&!uploading){const edit=document.createElement('button');edit.type='button';edit.className='attach-remove';edit.style.color='#5d4037';edit.textContent='✎ Edit / compress';edit.onclick=()=>editImage(i);detail.append(edit)}detail.append(name,meta,cap,remove);row.append(thumb,detail);list.append(row)});$('attachCount').textContent=staged.length+' file'+(staged.length===1?'':'s');$('attachSend').disabled=uploading||!staged.length;$('attachSend').textContent=uploading?'Sending…':'Send ➤'}
$('recordVoice').onclick=async()=>{
 if(!selected){notify('Select a contact first');return}
 if(voiceRecorder&&voiceRecorder.state==='recording'){
   voiceRecorder.stop();$('recordVoice').textContent='🎙';$('recordVoice').title='Record voice note';return;
 }
 if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){notify('Voice recording is not supported in this browser');return}
 try{
  voiceStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true}});
  const formats=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'];const format=formats.find(x=>MediaRecorder.isTypeSupported(x));
  voiceChunks=[];voiceRecorder=new MediaRecorder(voiceStream,format?{mimeType:format}:undefined);voiceStarted=Date.now();
  voiceRecorder.ondataavailable=e=>{if(e.data.size)voiceChunks.push(e.data)};
  voiceRecorder.onerror=()=>notify('Voice recording failed');
  voiceRecorder.onstop=()=>{voiceStream?.getTracks().forEach(t=>t.stop());voiceStream=null;const type=voiceRecorder.mimeType||format||'audio/webm';const blob=new Blob(voiceChunks,{type});voiceChunks=[];if(!blob.size){notify('No audio captured');return}if(blob.size>maxFile){notify('Voice note exceeds 15 MB');return}const ext=type.includes('mp4')?'m4a':type.includes('ogg')?'ogg':'webm';const file=new File([blob],`Voice note ${new Date().toISOString().slice(0,19).replace(/[T:]/g,'-')}.${ext}`,{type});if(staged.length>=10){notify('Maximum 10 attachments');return}staged.push({file,caption:'',url:URL.createObjectURL(file)});$('attachModal').hidden=false;renderStage()};
  voiceRecorder.start(250);$('recordVoice').textContent='■';$('recordVoice').title='Stop recording and preview';notify('Recording voice note. Tap ■ to stop and review before sending.');
 }catch(e){voiceStream?.getTracks().forEach(t=>t.stop());notify('Microphone unavailable: '+e.message)}
};
$('attachment').onchange=()=>{if(!selected){notify('Select a contact first');$('attachment').value='';return}for(const file of Array.from($('attachment').files)){if(file.size<1||file.size>maxFile){notify(file.name+': maximum size is 15 MB');continue}if(staged.length>=10){notify('Select up to 10 files at a time');break}staged.push({file,caption:'',url:URL.createObjectURL(file)})}$('attachment').value='';if(staged.length){$('attachModal').hidden=false;renderStage()}};

async function trimVideo(i){
 const item=staged[i];if(!item||uploading)return;
 const box=document.createElement('div');box.className='editor-overlay';
 box.innerHTML='<div class="editor-card"><div class="editor-title"><strong>Trim video</strong><button type="button" id="vtClose">✕</button></div><video id="vtVideo" controls playsinline preload="metadata" style="width:100%;max-height:45vh"></video><div class="editor-tools"><label>Start (seconds) <input id="vtStart" type="number" min="0" step=".1" value="0" style="width:85px"></label><label>End (seconds) <input id="vtEnd" type="number" min="0" step=".1" style="width:85px"></label></div><div class="editor-actions"><span id="vtStatus">Choose a segment</span><button type="button" id="vtSave">Trim and preview</button></div></div>';
 document.body.append(box);const v=box.querySelector('#vtVideo');v.src=item.url;
 v.onloadedmetadata=()=>{box.querySelector('#vtEnd').value=v.duration.toFixed(1);box.querySelector('#vtEnd').max=v.duration};
 const close=()=>{v.pause();v.removeAttribute('src');v.load();box.remove()};
 box.querySelector('#vtClose').onclick=close;
 box.querySelector('#vtSave').onclick=async()=>{
  const start=+box.querySelector('#vtStart').value,end=+box.querySelector('#vtEnd').value;
  if(!Number.isFinite(v.duration)||start<0||end>v.duration+.05||end-start<.3){notify('Choose a valid video segment');return}
  if(typeof v.captureStream!=='function'||typeof MediaRecorder==='undefined'){notify('Video trimming is unavailable in this browser. The original video is unchanged.');return}
  const type=['video/webm;codecs=vp8,opus','video/webm'].find(t=>MediaRecorder.isTypeSupported(t));
  if(!type){notify('This browser cannot encode a trimmed video.');return}
  const btn=box.querySelector('#vtSave');btn.disabled=true;box.querySelector('#vtStatus').textContent='Processing video…';
  try{
   v.pause();v.currentTime=start;await new Promise((resolve,reject)=>{if(Math.abs(v.currentTime-start)<.08)return resolve();v.addEventListener('seeked',resolve,{once:true});setTimeout(()=>reject(Error('Video seek timed out')),12000)});
   const media=v.captureStream();const chunks=[];const rec=new MediaRecorder(media,{mimeType:type,videoBitsPerSecond:1400000});
   rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};
   const done=new Promise((resolve,reject)=>{rec.onstop=resolve;rec.onerror=()=>reject(Error('Video encoding failed'))});
   rec.start(250);await v.play();
   await new Promise(resolve=>{const timer=setInterval(()=>{if(v.currentTime>=end||v.ended){clearInterval(timer);resolve()}},70);v.addEventListener('ended',()=>{clearInterval(timer);resolve()},{once:true})});
   rec.stop();v.pause();await done;
   const blob=new Blob(chunks,{type:'video/webm'});if(!blob.size||blob.size>maxFile)throw Error('Trimmed video is empty or exceeds 15 MB');
   const file=new File([blob],item.file.name.replace(/\.[^.]+$/,'')+'-trimmed.webm',{type:'video/webm'});
   URL.revokeObjectURL(item.url);item.file=file;item.url=URL.createObjectURL(file);item.token=null;close();renderStage();
  }catch(e){notify('Could not trim video: '+e.message);btn.disabled=false;box.querySelector('#vtStatus').textContent='Original video is unchanged'}
 };
}
async function editImage(i){
 const item=staged[i];if(!item||uploading)return;
 const img=new Image();img.src=item.url;await img.decode();let angle=0,crop=false,quality=.82,drawMode=false,strokes=[],activeStroke=null;
 const modal=document.createElement('div');modal.className='editor-overlay';modal.innerHTML='<div class="editor-card"><div class="editor-title"><strong>Edit image</strong><button type="button" id="edCancel">✕</button></div><canvas id="edCanvas"></canvas><div class="editor-tools"><button type="button" id="edRotate">↻ Rotate</button><button type="button" id="edCrop">□ Square crop</button><button type="button" id="edPen">✎ Draw</button><button type="button" id="edUndo">↶ Undo</button><label>Pen color <input id="edColor" type="color" value="#ff3030"></label><label>Quality <input id="edQuality" type="range" min="40" max="100" value="82"></label></div><div class="editor-actions"><span id="edSize"></span><button type="button" id="edSave">Save changes</button></div></div>';
