 draw();canvas.style.touchAction='none';canvas.addEventListener('pointerdown',e=>{if(!drawMode)return;canvas.setPointerCapture(e.pointerId);activeStroke=[];strokes.push(activeStroke);const r=canvas.getBoundingClientRect();activeStroke.push({x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height,color:modal.querySelector('#edColor').value})});canvas.addEventListener('pointermove',e=>{if(!activeStroke)return;const r=canvas.getBoundingClientRect();activeStroke.push({x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height)),color:activeStroke[0].color});draw()});canvas.addEventListener('pointerup',()=>{activeStroke=null});canvas.addEventListener('pointercancel',()=>{activeStroke=null});modal.querySelector('#edPen').onclick=()=>{drawMode=!drawMode;modal.querySelector('#edPen').textContent=drawMode?'✓ Drawing on':'✎ Draw'};modal.querySelector('#edUndo').onclick=()=>{strokes.pop();draw()};modal.querySelector('#edRotate').onclick=()=>{angle=(angle+90)%360;draw()};modal.querySelector('#edCrop').onclick=()=>{crop=!crop;draw()};modal.querySelector('#edQuality').oninput=e=>{quality=+e.target.value/100;draw()};modal.querySelector('#edCancel').onclick=()=>modal.remove();
 modal.querySelector('#edSave').onclick=()=>{canvas.toBlob(blob=>{if(!blob){notify('Unable to edit this image');return}if(blob.size>maxFile){notify('Edited image exceeds 15 MB');return}URL.revokeObjectURL(item.url);item.file=new File([blob],item.file.name.replace(/\.[^.]+$/,'')+'.jpg',{type:'image/jpeg'});item.url=URL.createObjectURL(item.file);item.token=null;modal.remove();renderStage();},'image/jpeg',quality)};
}
