let swipeStart=null;
$('messages').addEventListener('touchstart',e=>{const bubble=e.target.closest('[data-message-id]');if(!bubble||e.touches.length!==1||e.target.closest('button,a,video,audio,input'))return;swipeStart={x:e.touches[0].clientX,y:e.touches[0].clientY,id:+bubble.dataset.messageId,bubble,active:false}},{passive:true});
