function stopRingtone(){if(ringTimer){clearInterval(ringTimer);ringTimer=null}ringMode=null}
function unlockRingtone(){try{ringCtx=ringCtx||new (window.AudioContext||window.webkitAudioContext)();if(ringCtx.state==='suspended')ringCtx.resume().catch(()=>{})}catch(e){}}
function ringPulse(){if(!ringCtx||ringCtx.state!=='running')return;const now=ringCtx.currentTime;const incoming=ringMode==='incoming';const tones=incoming?[659.25,830.61,987.77]:[440,523.25];const freq=tones[ringStep++%tones.length];const osc=ringCtx.createOscillator(),gain=ringCtx.createGain();osc.type='sine';osc.frequency.value=freq;gain.gain.setValueAtTime(0.0001,now);gain.gain.exponentialRampToValueAtTime(incoming?.055:.035,now+.025);gain.gain.exponentialRampToValueAtTime(.0001,now+.23);osc.connect(gain).connect(ringCtx.destination);osc.start(now);osc.stop(now+.25)}
function startRingtone(mode){if(ringMode===mode)return;stopRingtone();ringMode=mode;ringStep=0;ringPulse();ringTimer=setInterval(ringPulse,mode==='incoming'?330:950)}
document.addEventListener('pointerdown',unlockRingtone,{once:true});document.addEventListener('keydown',unlockRingtone,{once:true});
let callStartedAt=0,callClock=null,facingMode='user',screenTrack=null;
function callStatus(value){$('callStatus').textContent=value}
function callClockStart(){if(callClock)clearInterval(callClock);callStartedAt=Date.now();callClock=setInterval(()=>{const t=Math.floor((Date.now()-callStartedAt)/1000);$('callTimer').textContent=String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0')},1000)}
function callClockStop(){if(callClock)clearInterval(callClock);callClock=null;$('callTimer').textContent='00:00'}
async function media(kind){
 if(!navigator.mediaDevices?.getUserMedia||!window.RTCPeerConnection)throw Error('Calls require a modern browser and HTTPS');
 stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:kind==='video'?{facingMode:'user'}:false});
 $('local').srcObject=stream;$('local').style.display=kind==='video'?'block':'none';$('camera').style.display=kind==='video'?'':'none';$('flipCamera').style.display=kind==='video'?'':'none';$('shareScreen').style.display=kind==='video'?'':'none';$('callbox').classList.toggle('audio-only',kind!=='video');
 pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});
 stream.getTracks().forEach(t=>pc.addTrack(t,stream));
 pc.ontrack=e=>{ $('remote').srcObject=e.streams[0]; if(e.track.kind==='audio')$('remote').play().catch(()=>callStatus('Tap the call screen to enable audio')) };
 pc.onicecandidate=e=>{if(e.candidate&&currentCall)api('signal',{call:currentCall.id,payload:{type:'candidate',candidate:e.candidate}}).catch(console.warn)};
 pc.onconnectionstatechange=()=>{if(!pc)return;const st=pc.connectionState;callStatus(st==='connected'?'Call connected · encrypted media transport':st==='connecting'?'Connecting…':st==='disconnected'?'Connection interrupted — reconnecting…':st==='failed'?'Connection failed. A TURN server may be required.':st==='closed'?'Call ended':'Establishing secure media…');if(st==='connected'){stopRingtone();if(!callClock)callClockStart()}};
 $('callbox').style.display='flex';callStatus('Connecting securely…');
}
async function startCall(kind){if(!selected||currentCall)return;try{const c=await api('call',{user:selected,kind});currentCall={id:c.id,kind,caller_id:me,callee_id:selected,status:'ringing'};lastSignal=0;$('calltitle').textContent='Calling…';unlockRingtone();startRingtone('outgoing');$('accept').style.display='none';await media(kind);const offer=await pc.createOffer();await pc.setLocalDescription(offer);await api('signal',{call:c.id,payload:{type:'offer',sdp:offer}})}catch(e){notify(e.message);await endCall()}}
async function acceptCall(){if(!currentCall)return;stopRingtone();try{answering=true;await media(currentCall.kind);await api('status',{call:currentCall.id,status:'active'});$('accept').style.display='none';$('calltitle').textContent='Connected';await pollSignals()}catch(e){notify(e.message);await endCall()}}
async function endCall(remote=false){stopRingtone();const id=currentCall?.id;currentCall=null;answering=false;lastSignal=0;pendingCandidates=[];callClockStop();if(screenTrack){screenTrack.stop();screenTrack=null}if(pc){pc.close();pc=null}if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}$('remote').srcObject=null;$('local').srcObject=null;$('callbox').style.display='none';$('accept').style.display='none';$('mute').textContent='Mute';$('camera').textContent='Camera off';$('shareScreen').textContent='Share screen';if(id&&!remote)try{await api('status',{call:id,status:'ended'})}catch(e){}}
async function pollSignals(){if(!currentCall)return;const d=await api('signals',null,'&call='+currentCall.id+'&after='+lastSignal);if(['ended','declined'].includes(d.status)){await endCall(true);return}for(const s of d.signals){lastSignal=Math.max(lastSignal,+s.id);const p=s.payload;if(p.type==='offer'&&pc){await pc.setRemoteDescription(p.sdp);const ans=await pc.createAnswer();await pc.setLocalDescription(ans);await api('signal',{call:currentCall.id,payload:{type:'answer',sdp:ans}})}else if(p.type==='answer'&&pc&&!pc.currentRemoteDescription){await pc.setRemoteDescription(p.sdp)}else if(p.type==='candidate'){if(pc?.remoteDescription)await pc.addIceCandidate(p.candidate);else pendingCandidates.push(p.candidate)}}if(pc?.remoteDescription){for(const c of pendingCandidates.splice(0))await pc.addIceCandidate(c)}}
async function refreshCalls(){try{if(!currentCall){const d=await api('calls');const incoming=d.calls.find(c=>+c.callee_id===me&&c.status==='ringing');if(incoming){currentCall=incoming;lastSignal=0;$('callbox').style.display='flex';$('callbox').classList.toggle('audio-only',incoming.kind!=='video');$('calltitle').textContent=(incoming.caller_name||'Colleague')+' is calling ('+incoming.kind+')';callStatus('Incoming call');startRingtone('incoming');$('accept').style.display='';$('local').style.display='none';$('camera').style.display='none';$('flipCamera').style.display='none';$('shareScreen').style.display='none';}}else if(pc)await pollSignals();else{const d=await api('calls');if(!d.calls.some(c=>+c.id===+currentCall.id))await endCall(true);}}catch(e){console.warn(e)}}
$('audio').onclick=()=>startCall('audio');$('video').onclick=()=>startCall('video');$('accept').onclick=acceptCall;$('hang').onclick=()=>endCall();
$('mute').onclick=()=>{const t=stream?.getAudioTracks()[0];if(t){t.enabled=!t.enabled;$('mute').textContent=t.enabled?'Mute':'Unmute'}};
$('camera').onclick=()=>{const t=stream?.getVideoTracks()[0];if(t){t.enabled=!t.enabled;$('camera').textContent=t.enabled?'Camera off':'Camera on'}};
$('flipCamera').onclick=async()=>{if(!pc||!stream?.getVideoTracks().length||screenTrack)return;const old=stream.getVideoTracks()[0];try{const next=facingMode==='user'?'environment':'user';const capture=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:next}},audio:false});const track=capture.getVideoTracks()[0];await pc.getSenders().find(s=>s.track?.kind==='video')?.replaceTrack(track);stream.removeTrack(old);old.stop();stream.addTrack(track);$('local').srcObject=stream;facingMode=next}catch(e){notify('Camera switch unavailable: '+e.message)}};
$('shareScreen').onclick=async()=>{if(!pc||!stream)return;const sender=pc.getSenders().find(s=>s.track?.kind==='video');if(!sender)return;if(screenTrack){screenTrack.stop();return}if(!navigator.mediaDevices.getDisplayMedia){notify('Screen sharing is not supported on this browser');return}try{const capture=await navigator.mediaDevices.getDisplayMedia({video:true,audio:false});const track=capture.getVideoTracks()[0];screenTrack=track;await sender.replaceTrack(track);$('local').srcObject=new MediaStream([track]);$('shareScreen').textContent='Stop sharing';track.onended=async()=>{if(screenTrack!==track)return;screenTrack=null;const camera=stream?.getVideoTracks()[0];if(pc&&camera)await sender.replaceTrack(camera);$('local').srcObject=stream;$('shareScreen').textContent='Share screen'}}catch(e){notify('Screen sharing unavailable: '+e.message)}};

refreshUsers();setInterval(()=>{if(!document.hidden){refreshUsers();refreshMessages();refreshCalls()}},2500);refreshCalls();

/* Ask the dashboard shell to fit this iframe above the Android keyboard. */
(function(){
  const field=document.getElementById('body');
  const panel=document.getElementById('messages');
  let lastHeight=0;
  function scrollToLatest(){requestAnimationFrame(()=>{panel.scrollTop=panel.scrollHeight;});}
  function signalKeyboard(active){
    try{window.parent.postMessage({type:'tcb-chat-keyboard',active:!!active},window.location.origin);}catch(e){}
  }
  field.addEventListener('focus',()=>{signalKeyboard(true);scrollToLatest();setTimeout(scrollToLatest,180);});
  field.addEventListener('blur',()=>{setTimeout(()=>signalKeyboard(false),100);});
  window.addEventListener('message',e=>{
    if(e.origin!==window.location.origin||!e.data||e.data.type!=='tcb-chat-viewport')return;
    if(e.data.height!==lastHeight){lastHeight=e.data.height;scrollToLatest();}
  });
  window.addEventListener('resize',()=>{if(document.activeElement===field)scrollToLatest();});
})();
</script></body></html>
